versions.variantCss:
.wemd-image-card[data-variant="bytedance-image-framed"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  overflow: hidden;
  margin: 16px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-image-card[data-variant="bytedance-image-framed"] .wemd-ic-image {
  width: 100%;
  display: block;
  margin: 0;
}
.wemd-image-card[data-variant="bytedance-image-framed"] .wemd-ic-image img {
  width: 100%;
  height: auto;
  display: block;
}
.wemd-image-card[data-variant="bytedance-image-framed"] .wemd-ic-caption {
  color: var(--wemd-text-soft);
  font-size: 13px;
  line-height: 1.6;
  padding: 12px 16px;
  margin: 0;
  text-align: center;
  border-top: 1px solid var(--wemd-border-soft);
}
